types-nonescaping-parameters.code:
fn apply(callback: fn() -> i64) -> i64 {
    const thunk = fn() -> i64 { return callback() + 1 }
    return thunk()
}
fn compose(f: escaping fn(i64) -> i64, g: escaping fn(i64) -> i64) -> fn(i64) -> i64 {
    return fn(x: i64) -> i64 { return f(g(x)) }
}

